def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))

    # Find the full line of color 2.
    line = None
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            line = ("row", r)
            break
    if line is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                line = ("col", c)
                break

    axis, pos = line
    obj = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] != bg and grid[r][c] != 2]

    if axis == "row":
        rmin = min(r for r, c in obj)
        rmax = max(r for r, c in obj)
        if rmax < pos:
            dr = pos - 1 - rmax
            stripe = rmin + dr - 1
        else:
            dr = pos + 1 - rmin
            stripe = rmax + dr + 1
        dc = 0
    else:
        cmin = min(c for r, c in obj)
        cmax = max(c for r, c in obj)
        if cmax < pos:
            dc = pos - 1 - cmax
            stripe = cmin + dc - 1
        else:
            dc = pos + 1 - cmin
            stripe = cmax + dc + 1
        dr = 0

    out = [row[:] for row in grid]
    for r, c in obj:
        out[r][c] = bg
    for r, c in obj:
        out[r + dr][c + dc] = grid[r][c]

    if axis == "row":
        for c in range(w):
            out[stripe][c] = 8
    else:
        for r in range(h):
            out[r][stripe] = 8

    return out
